#!/usr/bin/env node
// Turns vendor/chromium-autofill/legacy_regex_patterns.json into a small typed
// module, and in --check mode fails when the committed output has drifted.
//
// Generated rather than imported for three reasons. The vendored file is 126 KB
// of which we use about 4, it is JSON with `//` comments so nothing can require
// it directly, and a generated file that CI re-derives is the only way to know
// the committed copy still matches its source after a vendor bump.
//
// Run: node scripts/build-patterns.mjs [--check]
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = process.cwd();
const SOURCE = join(ROOT, 'vendor/chromium-autofill/legacy_regex_patterns.json');
const OUT = join(ROOT, 'src/fill/chromium-patterns.generated.ts');

/**
 * Chromium type -> our FieldKind. Only the types whose data we actually hold.
 *
 * Everything job-specific is absent from this file by design, not by omission:
 * the full 83-type list was checked and contains no work history, education,
 * authorization, salary or demographics. Those are pass 4's problem.
 */
const WANTED = {
  FIRST_NAME: 'given_name',
  LAST_NAME: 'family_name',
  FULL_NAME: 'full_name',
  EMAIL_ADDRESS: 'email',
  PHONE: 'phone',
  ADDRESS_LINE_1: 'address_line1',
  ADDRESS_LINE_2: 'address_line2',
  CITY: 'city',
  STATE: 'region',
  ZIP_CODE: 'postal_code',
  COUNTRY: 'country',
  COMPANY_NAME: 'current_employer',
};

/**
 * Types whose match means "this is NOT one of ours". Hand-rolled heuristics
 * always forget this half, which is most of why Chromium's patterns are worth
 * vendoring at all.
 *
 * `scope: null` vetoes every kind. A listed scope vetoes only those kinds,
 * because Chromium applies its IGNORED types as competing classifications
 * inside one group rather than as global rejections, and promoting them to
 * global would be actively wrong: `REGION_IGNORED` is literally
 * `province|region|other`, so a global version of it would veto the STATE
 * field it is meant to disambiguate. It is left out here for that reason, as
 * are the credit-card expiry patterns, whose bare `exp` would swallow
 * "experience".
 */
const VETO = [
  { type: 'SEARCH_TERM', scope: null },
  { type: 'CREDIT_CARD_NUMBER', scope: null },
  { type: 'CREDIT_CARD_VERIFICATION_CODE', scope: null },
  { type: 'ONE_TIME_CODE', scope: null },
  { type: 'IBAN_VALUE', scope: null },
  { type: 'MERCHANT_PROMO_CODE', scope: null },
  { type: 'NAME_IGNORED', scope: ['given_name', 'family_name', 'full_name', 'preferred_name'] },
  {
    type: 'ADDRESS_NAME_IGNORED',
    scope: ['address_line1', 'address_line2', 'city', 'region', 'postal_code', 'country'],
  },
  { type: 'ATTENTION_IGNORED', scope: ['address_line1', 'address_line2'] },
];

/** English only. A Spanish pattern applied to an English form matches noise. */
const LOCALE = 'en';

function load() {
  // The file opens with a `//` licence header and uses `"__comment__"` inside
  // the object, so only the leading line comments have to go.
  const text = readFileSync(SOURCE, 'utf8').replace(/^\s*\/\/.*$/gm, '');
  return JSON.parse(text);
}

function variantsFor(all, type) {
  const entries = all[type]?.[LOCALE] ?? [];
  return entries
    .filter((v) => v && typeof v.positive_pattern === 'string')
    .map((v) => ({
      positive: v.positive_pattern,
      negative: typeof v.negative_pattern === 'string' ? v.negative_pattern : null,
      score: typeof v.positive_score === 'number' ? v.positive_score : 1,
      attributes: (v.match_field_attributes ?? []).map((a) => a.toUpperCase()),
      controls: (v.form_control_types ?? []).map((c) => c.toUpperCase()),
    }));
}

function build() {
  const all = load();
  const missing = [...Object.keys(WANTED), ...VETO.map((v) => v.type)].filter((t) => !all[t]);
  if (missing.length) {
    // A silently dropped type would look exactly like a pattern that never
    // matches, which is the failure mode this whole file exists to avoid.
    throw new Error(`these types are not in the vendored file: ${missing.join(', ')}`);
  }

  const positives = Object.entries(WANTED).map(([type, kind]) => ({
    type,
    kind,
    variants: variantsFor(all, type),
  }));
  const vetoes = VETO.map(({ type, scope }) => ({
    type,
    scope,
    variants: variantsFor(all, type),
  }));

  const empty = [...positives, ...vetoes].filter((e) => e.variants.length === 0);
  if (empty.length) {
    throw new Error(`no ${LOCALE} variants for: ${empty.map((e) => e.type).join(', ')}`);
  }

  const count = [...positives, ...vetoes].reduce((n, e) => n + e.variants.length, 0);
  const body = JSON.stringify({ positives, vetoes }, null, 2);

  return `// GENERATED by scripts/build-patterns.mjs. Do not edit.
// Source: vendor/chromium-autofill/legacy_regex_patterns.json (BSD-3-Clause,
// see vendor/chromium-autofill/README.md). Locale "${LOCALE}", ${count} variants
// across ${positives.length} field types and ${vetoes.length} vetoes.
//
// Regenerate with \`pnpm patterns\`. CI runs \`pnpm patterns:check\`, which fails
// when this file and the vendored source have drifted apart.
import type { FieldKind } from './types';

export interface PatternVariant {
  readonly positive: string;
  readonly negative: string | null;
  readonly score: number;
  /** Chromium's attribute names: LABEL, NAME, and so on. */
  readonly attributes: readonly string[];
  /** Chromium's control-type names: INPUT_TEXT, SELECT_ONE, and so on. */
  readonly controls: readonly string[];
}

export interface PatternEntry {
  readonly type: string;
  readonly kind: FieldKind;
  readonly variants: readonly PatternVariant[];
}

export interface VetoEntry {
  readonly type: string;
  /** null vetoes every kind; a list vetoes only those kinds. */
  readonly scope: readonly FieldKind[] | null;
  readonly variants: readonly PatternVariant[];
}

export const CHROMIUM_PATTERNS: {
  readonly positives: readonly PatternEntry[];
  readonly vetoes: readonly VetoEntry[];
} = ${body} as const;
`;
}

const generated = build();
const check = process.argv.includes('--check');
let current = '';
try {
  current = readFileSync(OUT, 'utf8');
} catch {}

if (check) {
  if (current !== generated) {
    console.error(
      'patterns: src/fill/chromium-patterns.generated.ts is out of date.\n' +
        '  Run `pnpm patterns` and commit the result.',
    );
    process.exit(1);
  }
  console.log('patterns: the generated module matches the vendored source');
} else {
  writeFileSync(OUT, generated);
  console.log(`patterns: wrote ${OUT}`);
}
